#include <v8.h>
#include <assert.h>

using namespace v8;

static Local<Value> createDOMException(int errorCode, const char* message) {
  Isolate* isolate = Isolate::GetCurrent();
  Local<Context> context = isolate->GetCurrentContext();
  assert(!context.IsEmpty());
  Local<Value> exception;

  switch (errorCode) {
    case 1:
      exception = Exception::Error(String::NewFromUtf8(isolate, message).ToLocalChecked());
      break;
    case 2:
      exception = Exception::TypeError(String::NewFromUtf8(isolate, message).ToLocalChecked());
      break;
    case 3:
      exception = Exception::RangeError(String::NewFromUtf8(isolate, message).ToLocalChecked());
      break;
    case 4:
      exception = Exception::SyntaxError(String::NewFromUtf8(isolate, message).ToLocalChecked());
      break;
    case 5:
      exception = Exception::ReferenceError(String::NewFromUtf8(isolate, message).ToLocalChecked());
      break;
    default:
      exception = Exception::Error(String::NewFromUtf8(isolate, message).ToLocalChecked());
  }

  Local<Object> obj = exception->ToObject(context).ToLocalChecked();
  Local<String> stack = String::NewFromUtf8(isolate, "Stack trace here for debugging").ToLocalChecked();
  obj->Set(context, String::NewFromUtf8(isolate, "stack").ToLocalChecked(), stack).Check();

  return exception;
}

static void throwException(int errorCode, const char* message) {
  Isolate* isolate = Isolate::GetCurrent();
  if (isolate->IsExecutionTerminating()) {
    return;
  }

  Local<Value> exception = createDOMException(errorCode, message);
  isolate->ThrowException(exception);
}

#include <v8.h>
