// Function to create a DOM exception based on the error code
void createDOMException(v8::Isolate* isolate, int errorCode, const char* message) {
    v8::HandleScope handleScope(isolate);
    v8::Local<v8::Context> context = isolate->GetCurrentContext();

    assert(!v8::Isolate::GetCurrent()->InContext() || context.IsEmpty());

    v8::Local<v8::Value> exception;
    switch (errorCode) {
        case 1: // General error
            exception = v8::Exception::Error(v8::String::NewFromUtf8(isolate, message).ToLocalChecked());
            break;
        case 2: // Type error
            exception = v8::Exception::TypeError(v8::String::NewFromUtf8(isolate, message).ToLocalChecked());
            break;
        case 3: // Range error
            exception = v8::Exception::RangeError(v8::String::NewFromUtf8(isolate, message).ToLocalChecked());
            break;
        case 4: // Syntax error
            exception = v8::Exception::SyntaxError(v8::String::NewFromUtf8(isolate, message).ToLocalChecked());
            break;
        case 5: // Reference error
            exception = v8::Exception::ReferenceError(v8::String::NewFromUtf8(isolate, message).ToLocalChecked());
            break;
        default:
            exception = v8::Exception::Error(v8::String::NewFromUtf8(isolate, "Unknown error").ToLocalChecked());
    }

    if (!context.IsEmpty()) {
        v8::Local<v8::Object> error = v8::Object::New(isolate);
        error->Set(context, v8::String::NewFromUtf8(isolate, "message").ToLocalChecked(), exception).Check();
        error->Set(context, v8::String::NewFromUtf8(isolate, "stack").ToLocalChecked(), v8::StackTrace::CurrentStackTrace(isolate, 10)).Check();
        exception = error;
    }

    throwException(isolate, exception);
}

// Function to throw the exception in the V8 isolate
void throwException(v8::Isolate* isolate, v8::Local<v8::Value> exception) {
    if (isolate->InContext() && !isolate->IsExecutionTerminating()) {
        isolate->ThrowException(exception);
    }
}

